[1197] = { en = "The Sacred Flame", tier = 2,
  t = "De heilige vlam",
  d = "Met het water dat je hebt meegebracht, kun je de vlam die het relikwie van de centauren bewaart, tijdelijk doven. Maar het werkt niet voor altijd, dus je moet snel zijn.$b$bSplithoof Crag, het bolwerk van de centauren, ligt ten noorden van hier. De vlam wordt bewaard in Splithoof Hold, een zwaar bewaakt deel van de rotsen.$b$bWees wel voorzichtig. De Galak-centauren zijn hier met heel veel, en ze zullen iets wat hun zo dierbaar is niet graag afgeven.",
  o = "Haal de Cloven Hoof op voor Rau Cliffrunner bij Freewind Post.",
  p = "Ik wil de Cloven Hoof heel graag in mijn handen hebben. Heb je hem al gepakt?",
  c = "Ik voel een vreemde energie die uit de Hoof komt... Ik twijfel er niet aan dat we door hem te bestuderen verrassende nieuwe dingen over de centauren zullen ontdekken.$b$bBedankt, $n. Nu moet ik beginnen om de geheimen te ontcijferen die je me hebt gebracht.",
