  t = "Melor stuurt bericht",
  d = "$N, Melor Stonehoof heeft gehoord wat je hebt gedaan. Hij heeft een pad voor je uitgezet.$B$BAls je dat pad wilt volgen, ga dan naar Thunder Bluff en spreek met Melor. Je vindt hem op Hunter's Rise.",
