[1131] = { en = "Steelsnap", tier = 2,
  t = "Steelsnap",
  d = "Soms jagen we voor voedsel. Soms jagen we voor eer. En soms jagen we om de lessen van de Earthmother te verdienen.$B$BMaar de jacht die ik je nu opdraag, is niets van dit alles. Je moet een wezen doden dat buiten de zegen van de Earthmother staat.$B$BDe hyena Steelsnap zwerft rond in Thousand Needles, ten zuiden van de Barrens. Hij is een tiran. Hij trekt andere hyena's naar zich toe en verspreidt angst en bloedvergieten onder vreedzamere dieren.$B$BVind Steelsnap, $N. Vind hem en versla hem.",
  o = "Breng Steelsnap's Rib naar Melor Stonehoof in Thunder Bluff.",
  p = "Heb je de smerige Steelsnap verslagen, $N?",
  c = "Door het wezen Steelsnap te verslaan, heb je Thousand Needles gereinigd van een vreselijke smet.$B$BEn dat, $N, is je les voor vandaag.",
  g = { {"eer", "honour"}, {"opdraag", "assign, set upon (opdragen)"}, {"zegen", "blessing"}, {"zwerft rond", "roams around (rondzwerven)"}, {"tiran", "tyrant"}, {"verspreidt", "spreads (verspreiden)"}, {"bloedvergieten", "bloodshed"}, {"vreedzamere", "more peaceful (vreedzaam)"}, {"smerige", "foul, filthy (smerig)"}, {"gereinigd", "cleansed (reinigen)"}, {"smet", "taint, stain"} },
},

[1136] = { en = "Frostmaw", tier = 3,
  t = "Frostmaw",
  d = "$N, het is nu tijd om naar verre landen te reizen. Je bent er klaar voor.$B$BJe jaagt nu op Frostmaw, een yeti in de Alterac Mountains. Hij is moeilijk te vinden; zijn witte vacht gaat op in de sneeuw van zijn thuis in de bergen. Hij laat zich zelden zien.$B$BMaar ik zal je laten zien hoe je een wezen als hij kunt lokken. Hier, neem deze rol. Ik heb erop geschreven hoe Frostmaw gelokt kan worden.$B$BGa nu, $N. Je reis is lang en er wachten vele uitdagingen op je. Pas als je terugkomt met de manen van Frostmaw, is je taak voltooid.",
  o = "Breng Frostmaw's Mane naar Melor Stonehoof in Thunder Bluff.",
  p = "Ben je in de Alterac Mountains geweest, $N? Ben je de strijd aangegaan met de ongrijpbare Frostmaw?",
  c = "Er waren zowel kracht als sluwheid nodig om Frostmaw te vinden en te verslaan, $N. Jij hebt ze allebei.$B$BJe pad heeft je naar de dalen van Thousand Needles gebracht en naar de hoge bergen van Alterac. Op een dag zal het je door alle landen van de Earthmother leiden, want zo is de weg van de jager.",
  g = { {"vacht", "fur, coat"}, {"gaat op in", "blends into (opgaan in)"}, {"zelden", "rarely"}, {"lokken", "to lure, entice"}, {"rol", "scroll"}, {"gelokt", "lured (lokken)"}, {"uitdagingen", "challenges (uitdaging)"}, {"manen", "mane"}, {"voltooid", "completed (voltooien)"}, {"de strijd aangegaan", "taken up the fight (de strijd aangaan)"}, {"ongrijpbare", "elusive (ongrijpbaar)"}, {"sluwheid", "cunning"}, {"dalen", "valleys (dal)"} },
},

[2440] = { en = "The Platinum Discs", tier = 4,
  t = "De platina schijven",
  d = "Ik zal mijn krachten op deze schijven richten. Na verloop van tijd zullen ze mij laten zien hoe ze echt werken.$B$BWat jou betreft, $N: ik zal je nu belonen voor je ijver, omdat je dit onder mijn aandacht hebt gebracht. Breng deze bon naar Bena Winterhoof, de alchemietrainer van Thunder Bluff. Ze zal je een speciaal voorwerp geven dat je volgens mij aantrekkelijk zult vinden, en ze laat je kiezen uit drankjes uit mijn eigen voorraad.$B$BKom snel bij me terug, want ik voel dat we nog veel moeten doen met deze vondst.",
  o = "Breng de beloningsbon naar Bena Winterhoof in Thunder Bluff.",
  p = "Gegroet, $c! Kom je voor alchemietraining, of misschien voor iets anders?",
  c = "Nou, $N, je hebt Sage Truthseeker vast heel tevreden gemaakt, als hij je dit voorwerp geeft. Je krijgt ook een geschenk uit zijn voorraad drankjes: als beloning mag je kiezen tussen 5 Superior Healing Potions of 5 Greater Mana Potions.",
  g = { {"platina", "platinum"}, {"schijven", "discs (schijf)"}, {"na verloop van tijd", "in due time, over time"}, {"ijver", "diligence"}, {"onder mijn aandacht", "to my attention"}, {"bon", "voucher"}, {"aantrekkelijk", "appealing, attractive"}, {"voorraad", "stock, supply"}, {"vondst", "find, discovery"}, {"beloningsbon", "reward voucher"}, {"geschenk", "gift"} },
},

[2965] = { en = "Portents of Uldum", tier = 4,
  t = "Voortekenen van Uldum",
  d = "Ah, $n, wat een geluk dat je weer naar me toe komt. Jouw ontdekkingen bij de opgraving in Uldaman hebben ons, wijzen, zeker veel stof tot praten gegeven. Daar sprak ik net over met een van de druïden, Nara Wildmane, toen het tot me doordrong dat haar eerdere avonturen weleens heel belangrijk konden zijn voor de volgende stap die we moeten zetten.$B$BIk wil graag dat je met haar praat over haar reizen naar de Valley of the Watchers in de woestijn van Tanaris. Ze wacht op je op de Elder Rise.",
  o = "Spreek met Nara Wildmane op de Elder Rise in Thunder Bluff.",
  c = "Diep in de woestijn van Tanaris ligt een plek die de Valley of the Watchers heet. De schijven die je hebt gevonden... in hun vertaalde tekens wordt een plek genoemd die Uldum heet. De meesten denken dat die plek een mythe is.$B$BIk weet dat dat niet klopt: Uldum bestaat. Ik ben er geweest. Nou... aan de buitenkant, in elk geval.$B$BWaar het om gaat, $N, is dit: we denken dat er een verband is tussen de schijven en Uldum, en we willen dat jij erheen gaat.",
  g = { {"voortekenen", "portents, omens (voorteken)"}, {"opgraving", "dig site, excavation"}, {"wijzen", "sages (wijze)"}, {"stof tot praten", "much to discuss"}, {"druïden", "druids (druïde)"}, {"tot me doordrong", "dawned on me (doordringen)"}, {"weleens", "possibly, might well"}, {"woestijn", "desert"}, {"tekens", "signs, glyphs (teken)"}, {"mythe", "myth"}, {"verband", "connection"} },
},

[2966] = { en = "Seeing What Happens", tier = 4,
  t = "Kijken wat er gebeurt",
  d = "Sage Truthseeker en ik willen graag dat je de kleine schijven die je hebt gevonden, naar de gesloten poorten van Uldum brengt. We... we weten niet zeker wat er gebeurt als je dat doet.$B$BDit klinkt riskant, zeker, dat geven we toe. Maar misschien gebeurt er ook helemaal niets. Misschien moet je de schijven ergens op gebruiken. Misschien gaan de deuren open als je de schijven bij je hebt. Sta open om alles te proberen, en wees erop voorbereid dat alles kan gebeuren.$B$BLeer wat je kunt en kom dan bij me terug. We zullen veel te bespreken hebben.",
  o = "Breng de kleine platina schijven naar de poorten van Uldum in Tanaris en zoek naar aanwijzingen voor het verband tussen die twee.",
  p = "Deze sokkel, die er bekend uitziet, steekt uit het hete zand. Misschien heeft het een reden dat hij hier staat...",
  c = "Als je de sokkel aanraakt, zoemen en gloeien de kleine schijven uit Uldaman in je rugzak. Een bekend, tintelend gevoel gaat over je handen, terwijl het beeld van nog een Stone Watcher tot leven komt voor de poorten van Uldum.$B$B\"Gegroet. Ik ben een bewaker van de toegang. Bij de schijven die voor toegang zijn gebruikt, ontbreken de juiste toegangsschijven: de Plates of Uldum. Voeg deze platen toe aan de structuur van de schijven en herhaal je toegangsreeks. Dank je.\"",
  g = { {"poorten", "gates (poort)"}, {"riskant", "risky"}, {"dat geven we toe", "we acknowledge that (toegeven)"}, {"voorbereid", "prepared (voorbereiden)"}, {"aanwijzingen", "clues (aanwijzing)"}, {"sokkel", "pedestal"}, {"zoemen", "to hum"}, {"gloeien", "to glow"}, {"tintelend", "tingling (tintelen)"}, {"toegang", "access, entry"}, {"ontbreken", "are missing (ontbreken)"}, {"voeg ... toe", "add (toevoegen)"}, {"toegangsreeks", "access sequence"} },
},

[2967] = { en = "Return to Thunder Bluff", tier = 4,
  t = "Terug naar Thunder Bluff",
  d = "Je gebruikt de sokkel nog een keer; de platina schijven zitten opeens weer in je rugzak.$B$BJe weet nu wat de stenen wachter je heeft geleerd, en je hebt de schijven terug. Het is tijd om terug te gaan naar Thunder Bluff en Nara Wildmane over je ontdekking te vertellen.",
  o = "Spreek met Nara Wildmane in Thunder Bluff.",
  p = "Welkom terug, $N. Kon je de schijven goed gebruiken, of was het allemaal voor niets?",
  c = "Ontbraken er schijven? Interessant genoeg lijken de schijven van Norgannon maar een deel van de hele set te zijn - zoals sleutels aan een sleutelbos, zeg maar.$B$BAls we de Plates of Uldum kunnen vinden, dan kunnen we echt het Uldum-complex zelf binnengaan. Ik weet niet of ik daar enthousiast of doodsbang van moet worden.$B$BMisschien moeten we alles riskeren om ervoor te zorgen dat de geheimen die de aarde bewaart, en die ons allemaal zouden vernietigen, precies dat blijven: geheimen.",
  g = { {"opeens", "suddenly"}, {"wachter", "watcher, guard"}, {"voor niets", "for naught, in vain"}, {"ontbraken", "were missing (ontbreken)"}, {"interessant genoeg", "interestingly enough"}, {"sleutelbos", "key ring"}, {"zeg maar", "if you will, so to speak"}, {"doodsbang", "terrified"}, {"riskeren", "to risk"}, {"ervoor te zorgen", "to ensure (ervoor zorgen)"}, {"vernietigen", "to destroy"} },
},

[2968] = { en = "A Future Task", tier = 4,
  t = "Een taak voor later",
  d = "Nou, $n... we zitten jammer genoeg vast. We weten wat we nodig hebben - de Plates of Uldum - maar we hebben geen idee waar ze kunnen zijn. We gaan dit onderzoeken en daarna een goed aanvalsplan bedenken. Ik heb een paar ideeën waar we kunnen beginnen met zoeken. Ik heb goede hoop dat we je binnenkort zullen vragen om weer mee te helpen de waarheid te ontdekken.$B$BSage Truthseeker moet hiervan op de hoogte worden gebracht, $n. Hij wil je ongetwijfeld ook persoonlijk bedanken, omdat je weer gehoor hebt gegeven aan de oproep.",
  o = "Spreek met Sage Truthseeker in Thunder Bluff.",
  c = "Dan zijn we het allemaal eens: het beste is om te wachten tot we de gebieden kunnen beperken waar deze platen verborgen kunnen liggen. Je hebt ons zo ver gebracht, $N, en ik hoop dat jij degene bent die weer het veld in gaat om de geheimen van Uldum onder ogen te zien.$B$BSta me toe je intussen deze vergoeding te geven. Die zou alle kosten moeten dekken die je hebt gemaakt om ons te helpen, met nog iets extra's. Kom snel weer bij ons langs... Uldum roept ons allemaal, jong mens.",
  g = { {"jammer genoeg", "unfortunately"}, {"zitten vast", "are stuck (vastzitten)"}, {"aanvalsplan", "plan of attack"}, {"goede hoop", "high hopes"}, {"op de hoogte worden gebracht", "be informed"}, {"ongetwijfeld", "no doubt"}, {"gehoor hebt gegeven aan de oproep", "heeded the call"}, {"beperken", "to narrow down, limit"}, {"onder ogen te zien", "to face, confront (onder ogen zien)"}, {"vergoeding", "fee, honorarium"}, {"dekken", "to cover (costs)"} },
},

[3761] = { en = "Un'Goro Soil", tier = 4,
  t = "Grond van Un'Goro",
  d = "Men zegt dat de grond van Un'Goro Crater rijk is aan sterke magische eigenschappen. De Cenarion Circle wil deze grond in grote hoeveelheden bestuderen. Ga de wildernis van Un'Goro in en verzamel er genoeg van voor ons verdere onderzoek.$B$BDe rijke grond ligt hier en daar in hopen. Sommige dieren hebben misschien ook bruikbare monsters op hun lijf. Breng alles naar buiten, naar Ghede. Zoek gewoon naar de hopen aarde en de tauren die bevelen blaft. Hij bedoelt het goed, maar maak hem niet kwaad!",
  o = "Breng 20 monsters Un'Goro Soil naar Ghede op de Elder Rise van Thunder Bluff.",
  p = "Op de plaats rust, soldaat. Als je hier bent om grond uit Un'Goro af te leveren - uitstekend! Anders: wegwezen.",
  c = "Ja hoor, soldaat $N, doe vooral geen moeite om me te helpen deze grond op de hopen te gooien! Als de Great Spirits hadden gewild dat het gebeurde, dan hadden ze het er zelf met een wonder op gezet, toch?!$B$BArch Druid Runetotem wil je weer spreken. Maar voor zijn volgende taak merk je dat kennis van Herbalism op Journeyman-niveau handig zou zijn. Als je dat niet kent, vindt hij nog steeds wel een taak voor je.",
  g = { {"men zegt", "it is said, reportedly"}, {"eigenschappen", "qualities, properties (eigenschap)"}, {"hoeveelheden", "quantities (hoeveelheid)"}, {"wildernis", "wilds, wilderness"}, {"hopen", "piles (hoop)"}, {"bruikbare", "usable (bruikbaar)"}, {"monsters", "samples (monster)"}, {"bevelen", "orders (bevel)"}, {"blaft", "barks (blaffen)"}, {"op de plaats rust", "at ease (military)"}, {"wegwezen", "get lost, disappear"}, {"doe vooral geen moeite", "don't make any effort (sarcastic)"}, {"wonder", "miracle"} },
},

[3762] = { en = "Assisting Arch Druid Runetotem", tier = 4,
  t = "Arch Druid Runetotem helpen",
  d = "Pardon, $c, mag ik heel even je tijd, als dat kan?$B$BDe Cenarion Circle in Thunder Bluff is erg geïnteresseerd in ervaren avonturiers zoals jij, om hen te helpen bij een belangrijk onderzoeksproject. Ik ken de details niet, maar ik kan je vertellen dat niemand minder dan Hamuul Runetotem dit onderzoek leidt.$B$BAlsjeblieft - als je interesse hebt, spreek dan zelf met hem op de Elder Rise in Thunder Bluff.",
  o = "Spreek met Arch Druid Hamuul Runetotem in Thunder Bluff.",
  c = "Gegroet, $C. Ik ben blij dat je ons onderzoek wilt helpen. Er is veel te doen, en ik zou je tekortdoen als ik je vertelde dat dit werk niet gevaarlijk is. Hopelijk schrikt dat je niet af... maar zo te zien heb je al eerder met gevaar te maken gehad.",
  g = { {"ervaren", "seasoned, experienced"}, {"avonturiers", "adventurers (avonturier)"}, {"onderzoeksproject", "research project"}, {"niemand minder dan", "none other than"}, {"leidt", "leads (leiden)"}, {"tekortdoen", "to do a disservice"}, {"schrikt ... af", "scares off (afschrikken)"}, {"zo te zien", "from the looks of it"}, {"te maken gehad", "dealt with (te maken hebben met)"} },
},

[3782] = { en = "Morrowgrain Research", tier = 4,
  t = "Onderzoek naar morrowgrain",
  d = "Met wat wij een Evergreen Pouch noemen, hebben we Tharlendris-zaden gekweekt in de grond van Un'Goro Crater. Uit deze zaden zijn allerlei willekeurige, krachtige kruiden gegroeid. Een van de resultaten is morrowgrain, een geheimzinnig kruid waar we weinig over weten. Ik hoop heel erg dat ik dit raadsel voor de Circle kan oplossen.$B$BBreng deze bon naar mijn dochter Bashana. Zij geeft je dan wat zaden, zodat je ons kunt helpen. Als je zaden op zijn, moet je nieuwe bij haar kopen.",
  o = "Breng de Seed Voucher naar Bashana Runetotem in Thunder Bluff.",
  p = "Vrede en rust voor jou, vriend. Je komt voor zaken van de Arch Druid zelf, toch?",
  c = "Ja, deze bon is goed voor twintig zakjes zaden. Als je zaden op zijn, kunnen we je er meer geven. Helaas is het wel erg duur om Tharlendris-zaden in grote aantallen te maken. Daarom vraagt de Cenarion Circle aan wie ons helpt, om een deel van de kosten te dragen.$B$BWie terugkomt met morrowgrain, merkt dat de beloning van de Arch Druid de kosten ruim goedmaakt.",
  g = { {"zaden", "seeds (zaad)"}, {"gekweekt", "cultivated, grown (kweken)"}, {"willekeurige", "random (willekeurig)"}, {"kruiden", "herbs (kruid)"}, {"geheimzinnig", "mysterious"}, {"raadsel", "mystery, riddle"}, {"op zijn", "have run out (op zijn)"}, {"zakjes", "packets (zakje)"}, {"vrede en rust", "peace and serenity"}, {"kosten ... dragen", "bear the costs"}, {"ruim", "amply, more than"}, {"goedmaakt", "makes up for (goedmaken)"} },
},

[3786] = { en = "Morrowgrain Research", tier = 4,
  t = "Onderzoek naar morrowgrain",
  d = "Hier is je Evergreen Pouch, die je nodig hebt om de Tharlendis-zaden te gebruiken. Je moet ook monsters Un'Goro-grond bij je hebben, als mest voor de zaden. Gebruik de buidel gewoon als je alles hebt; de buidel doet de rest.$B$BAls je genoeg morrowgrain hebt, breng het dan naar mij, hier op de Elder Rise. Stoor de Arch Druid alsjeblieft niet; hij heeft het heel druk met het onderzoek en met alle zorgen die hij heeft!",
  o = "Gebruik een Evergreen Pouch met een Packet of Tharlendis Seeds en twee monsters Un'Goro Soil om te proberen Morrowgrain te kweken.$B$BBreng 10 Morrowgrain naar Bashana Runetotem in Thunder Bluff.",
  p = "Ja, $N, heb je al wat morrowgrain gekweekt voor het belangrijke onderzoek van de Arch Druid? De geheimzinnige eigenschappen van Un'Goro Crater worden elke dag duidelijker, dankzij de hulp die je ons geeft.",
  c = "Goed gedaan, $N. Ik zal deze zeker aan de Arch Druid zelf geven als hij ze nodig heeft. Neem intussen dit aan als teken van de waardering van de Cenarion Circle.$B$BOnze behoefte aan morrowgrain is voorlopig constant. Als je ons wilt blijven helpen, kom dan terug als je er meer van hebt gekweekt.",
  g = { {"mest", "fertilizer"}, {"buidel", "pouch"}, {"stoor", "disturb, bother (storen)"}, {"het druk hebben", "to be busy"}, {"zorgen", "worries, concerns (zorg)"}, {"kweken", "to grow, cultivate"}, {"dankzij", "thanks to"}, {"waardering", "appreciation"}, {"behoefte", "need"}, {"voorlopig", "for now"} },
},

[1000] = { en = "The New Frontier", tier = 4,
  t = "De nieuwe grens",
  d = "Opgelet, helden!$B$BDe Cenarion Circle zoekt sterke personen die willen helpen om de enorme nieuwe grensgebieden van Kalimdor te verkennen! Ver ten westen van Tanaris en Gadgetzan ligt een verboden woestenij vol onvoorstelbare gevaren, en de Circle heeft bereidwillige en eervolle vertegenwoordigers nodig die in hun plaats handelen.$B$BIedereen die interesse heeft, moet een gesprek aanvragen bij de Cenarion Circle. Spreek met Arch Druid Hamuul Runetotem op de Elder's Rise van Thunder Bluff voor meer informatie!",
  o = "Spreek met Arch Druid Hamuul Runetotem op de Elder Rise van Thunder Bluff over de oproep van de Cenarion Circle om de grensgebieden van Kalimdor te verkennen.",
  c = "Gegroet, $C.$b$bIk ben blij dat iemand zoals jij zich interesseert voor het welzijn van de natuur. De verhalen over je grote daden zijn je vooruitgegaan, en je bent hier welkom. Nu je voor me staat, heb ik er vertrouwen in dat de Cenarion Circle de hulp krijgt die ze nodig heeft.$b$bOnze band met de Cenarion Circle in Moonglade gaat verder dan de grenzen tussen rassen en politiek. Denk hieraan als je voor de Circle werkt, dan zal het je goed gaan.",
  g = { {"opgelet", "attention"}, {"grensgebieden", "frontiers, border regions (grensgebied)"}, {"verkennen", "to explore"}, {"verboden", "forbidden"}, {"woestenij", "wasteland"}, {"onvoorstelbare", "unimaginable (onvoorstelbaar)"}, {"bereidwillige", "willing (bereidwillig)"}, {"eervolle", "honourable (eervol)"}, {"vertegenwoordigers", "proxies, representatives (vertegenwoordiger)"}, {"welzijn", "well-being"}, {"zijn je vooruitgegaan", "precede you (voorgaan)"}, {"vertrouwen", "confidence, trust"}, {"band", "bond, connection"} },
},

[1123] = { en = "Rabine Saturna", tier = 4,
  t = "Rabine Saturna",
  d = "Voor deze taak zoekt Rabine Saturna, de hofmeester van Keeper Remulos in Moonglade, hulp bij het verkennen van de enorme woestenijen ver ten westen van Tanaris en Un'Goro. Hij is in Nighthaven, het belangrijkste dorp van Moonglade.$B$BIk wil je duidelijk maken hoe belangrijk jouw aanwezigheid is. De spanningen tussen de nachtelfen van Darnassus en de Cenarion Circle in Moonglade worden groter. Kijk verder dan de grenzen tussen rassen, en gebruik de wijsheid van je voorouders in je omgang met de Circle daar, $N. Veel succes.",
  o = "Spreek met Rabine Saturna in het dorp Nighthaven, Moonglade. Moonglade ligt tussen Felwood en Winterspring en is te bereiken via een pad vanuit Timbermaw Hold.",
  c = "Ik ben Rabine Saturna. Namens Keeper Remulos en alle bewoners van deze heilige open plek in het bos heet ik je welkom.$B$BIk waardeer je interesse en je gretigheid om de Cenarion Circle te helpen. De tauren hebben laten zien dat ze een opvallende aanleg hebben voor de leer van Cenarius, en via hen is de Horde welkom in de veiligheid van deze open plek. Het behoud van Azeroth is een doel dat we allebei delen.$B$BJe bent hier onder vrienden, $N.",
  g = { {"hofmeester", "majordomo, steward"}, {"woestenijen", "wastelands (woestenij)"}, {"aanwezigheid", "presence"}, {"spanningen", "tensions (spanning)"}, {"nachtelfen", "night elves (nachtelf)"}, {"voorouders", "ancestors (voorouder)"}, {"omgang", "dealings"}, {"bewoners", "inhabitants, denizens (bewoner)"}, {"open plek", "glade, clearing"}, {"gretigheid", "eagerness"}, {"aanleg", "aptitude, propensity"}, {"de leer", "the teachings, tenets"}, {"behoud", "preservation"} },
},

[3804] = { en = "Morrowgrain to Thunder Bluff", tier = 4,
  t = "Morrowgrain naar Thunder Bluff",
  p = "De Arch Druid zoekt altijd meer morrowgrain voor het onderzoeksproject van de Cenarion Circle naar Un'Goro Crater. We nemen ze per tien aan, en we belonen je met een voorraad spullen die je nuttig zult vinden. Laat het me weten als je er tien hebt, dan beloon ik je daarvoor.",
